pub fn deck_text(dst: &mut [u8], lit: &[u8]) -> usize {
    let mut i: usize = 0;
    while ((i < lit.len()) && (i < dst.len())) {
        if (lit[(i) as usize] == 126) {
            dst[(i) as usize] = 111;
        } else {
            dst[(i) as usize] = lit[(i) as usize];
        }
        i = (i + 1);
    }
    return i;
}

pub fn num_of(s: &[u8], st: &mut [usize]) -> bool {
    return parse_num(s, 0, s.len(), st);
}

pub fn time_expr(s: &[u8]) -> bool {
    return time_only(s, 0, s.len());
}

pub fn cell_diff(st: impl AsRef<[usize]>, n: usize, d: impl AsRef<[u32]>, nv: impl AsRef<[u32]>) -> usize {
    let st: &[usize] = st.as_ref();
    let d: &[u32] = d.as_ref();
    let nv: &[u32] = nv.as_ref();
    let mut miss: usize = 0;
    let mut i: usize = 0;
    while (i < (n * n)) {
        if ((st[(((CELL + CL_D) + i)) as usize] as u32) != d[(i) as usize]) {
            miss = (miss + 1);
        }
        i = (i + 1);
    }
    i = 0;
    while (i < n) {
        if ((st[(((CELL + CL_NV) + i)) as usize] as u32) != nv[(i) as usize]) {
            miss = (miss + 1);
        }
        i = (i + 1);
    }
    return miss;
}

