pub const SCALE: f64 = 16777216.0;

pub const WIDE: usize = 11;

pub fn eliminate(aug: [f64; 55], n: usize) -> [f64; 55] {
    let mut w: [f64; 55] = aug;
    let mut c: usize = 0;
    let mut r: usize = 0;
    let mut p: usize = 0;
    let mut k: usize = 0;
    while (c < n) {
        p = c;
        r = (c + 1);
        while (r < n) {
            if (fabs64(w[(((r * WIDE) + c)) as usize]) > fabs64(w[(((p * WIDE) + c)) as usize])) {
                p = r;
            }
            r = (r + 1);
        }
        if (p != c) {
            k = 0;
            while (k < WIDE) {
                let t: f64 = w[(((c * WIDE) + k)) as usize];
                w[(((c * WIDE) + k)) as usize] = w[(((p * WIDE) + k)) as usize];
                w[(((p * WIDE) + k)) as usize] = t;
                k = (k + 1);
            }
        }
        let piv: f64 = w[(((c * WIDE) + c)) as usize];
        k = 0;
        while (k < WIDE) {
            w[(((c * WIDE) + k)) as usize] = (w[(((c * WIDE) + k)) as usize] / piv);
            k = (k + 1);
        }
        r = 0;
        while (r < n) {
            if (r != c) {
                let f: f64 = w[(((r * WIDE) + c)) as usize];
                k = 0;
                while (k < WIDE) {
                    w[(((r * WIDE) + k)) as usize] = (w[(((r * WIDE) + k)) as usize] - (f * w[(((c * WIDE) + k)) as usize]));
                    k = (k + 1);
                }
            }
            r = (r + 1);
        }
        c = (c + 1);
    }
    return w;
}

pub fn fabs64(x: f64) -> f64 {
    if (x < 0.0) {
        return (0.0 - x);
    }
    return x;
}

pub fn is_free(node: u8) -> bool {
    return ((node != NODE_GND) && (node != NODE_IN));
}

pub fn ix(node: u8) -> usize {
    return ((node as usize) - 1);
}

pub fn mn_of(w: [f64; 55], n: usize) -> [f64; 30] {
    let mut o: [f64; 30] = [0.0; 30];
    let mut i: usize = 0;
    let mut j: usize = 0;
    while (i < n) {
        j = 0;
        while (j < n) {
            o[(((i * n) + j)) as usize] = w[((((i * WIDE) + n) + j)) as usize];
            j = (j + 1);
        }
        o[(((n * n) + i)) as usize] = w[(((i * WIDE) + (2 * n))) as usize];
        i = (i + 1);
    }
    return o;
}

pub fn pack(m: u32, neg: bool) -> u32 {
    if (m == 0) {
        return 0;
    }
    if neg {
        return (m | NEG);
    }
    return m;
}

pub fn q_sm(v: f64) -> u32 {
    return pack((((fabs64(v) * SCALE) + 0.5) as u32), (v < 0.0));
}

pub const B_DEL: u8 = 127;

pub const B_LOWER_A: u8 = 97;

pub const B_LOWER_Z: u8 = 122;

pub const B_NINE: u8 = 57;

pub const B_UNDERSCORE: u8 = 95;

pub const B_UPPER_A: u8 = 65;

pub const B_UPPER_Z: u8 = 90;

pub fn is_alpha(c: u8) -> bool {
    return ((((c >= B_LOWER_A) && (c <= B_LOWER_Z)) || is_upper(c)) || (c == B_UNDERSCORE));
}

pub fn is_digit(c: u8) -> bool {
    return ((c >= B_ZERO) && (c <= B_NINE));
}

pub fn is_space(c: u8) -> bool {
    return ((((c == B_SPACE) || (c == B_TAB)) || (c == B_NL)) || (c == B_CR));
}

pub fn is_upper(c: u8) -> bool {
    return ((c >= B_UPPER_A) && (c <= B_UPPER_Z));
}

pub fn out_is(w: usize, out: &[u8], from: usize, s: &[u8]) -> bool {
    if (((w < from) || ((w - from) != s.len())) || (w > out.len())) {
        return false;
    }
    let mut k: usize = 0;
    while (k < s.len()) {
        if (out[((from + k)) as usize] != s[(k) as usize]) {
            return false;
        }
        k = (k + 1);
    }
    return true;
}

pub fn put(st: &mut [usize], out: &mut [u8], c: u8) -> () {
    let w: usize = st[(W) as usize];
    if (w < out.len()) {
        out[(w) as usize] = c;
    }
    st[(W) as usize] = (w + 1);
}

pub fn put_num(st: &mut [usize], out: &mut [u8], v: usize) -> () {
    if (v >= 10) {
        put_num(st, out, (v / 10));
    }
    put(st, out, (B_ZERO + ((v % 10) as u8)));
}

pub fn put_text(src: &[u8], st: &mut [usize], out: &mut [u8], a: usize, b: usize, max: usize) -> () {
    let mut i: usize = a;
    while (((i < b) && (i < src.len())) && (i < (a + max))) {
        let c: u8 = src[(i) as usize];
        if ((c >= B_SPACE) && (c < B_DEL)) {
            put(st, out, c);
        } else {
            if ((c < 128) || (c >= 192)) {
                put(st, out, 63);
            }
        }
        i = (i + 1);
    }
}

pub fn puts(st: &mut [usize], out: &mut [u8], s: &[u8]) -> () {
    let mut i: usize = 0;
    while (i < s.len()) {
        put(st, out, s[(i) as usize]);
        i = (i + 1);
    }
}

